// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title USDC-SOL Escrow Platform
 * @dev Secure Maker-Taker escrow facilitating atomic ERC20 -> Native Token swap
 */
contract Escrow is ReentrancyGuard {
    address public maker;
    address public taker;
    IERC20 public usdcToken;
    uint256 public usdcAmount;
    uint256 public solAmountExpected;
    uint256 public expiry;
    bool public isCompleted;
    bool public isRefunded;

    event EscrowCreated(address indexed maker, uint256 amount, uint256 expiry);
    event EscrowExecuted(address indexed taker, uint256 solAmount);
    event EscrowRefunded();

    constructor(
        address _taker,
        address _usdcToken,
        uint256 _usdcAmount,
        uint256 _solAmountExpected,
        uint256 _duration
    ) {
        maker = msg.sender;
        taker = _taker;
        usdcToken = IERC20(_usdcToken);
        usdcAmount = _usdcAmount;
        solAmountExpected = _solAmountExpected;
        expiry = block.timestamp + _duration;
    }

    function executeSwap() external payable nonReentrant {
        require(msg.sender == taker, "Only designated taker can swap");
        require(block.timestamp <= expiry, "Escrow has expired");
        require(!isCompleted, "Already executed");
        require(!isRefunded, "Already refunded");
        require(msg.value == solAmountExpected, "Incorrect SOL amount sent");

        isCompleted = true;

        // Transfer USDC to Taker
        bool successUsdc = usdcToken.transfer(taker, usdcAmount);
        require(successUsdc, "USDC transfer failed");

        // Transfer SOL (msg.value) to Maker
        (bool successSol, ) = payable(maker).call{value: msg.value}("");
        require(successSol, "SOL transfer failed");

        emit EscrowExecuted(taker, msg.value);
    }

    function refund() external nonReentrant {
        require(msg.sender == maker, "Only maker can refund");
        require(block.timestamp > expiry, "Escrow has not expired yet");
        require(!isCompleted, "Already completed");
        require(!isRefunded, "Already refunded");

        isRefunded = true;

        bool success = usdcToken.transfer(maker, usdcAmount);
        require(success, "USDC refund failed");

        emit EscrowRefunded();
    }
}

